def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = my[-1]
    last_op = op[-1]

    op_c_total = sum(1 for x in op if x == 'C')
    my_d_total = sum(1 for x in my if x == 'D')
    op_d_total = n - op_c_total

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_d_streak += 1
        else:
            break

    w10 = 10 if n >= 10 else n
    recent_c = sum(1 for i in range(n - w10, n) if op[i] == 'C')
    recent_c_rate = recent_c / w10

    w5 = 5 if n >= 5 else n
    recent5_c = sum(1 for i in range(n - w5, n) if op[i] == 'C')
    recent5_rate = recent5_c / w5

    trans_len = 12 if n >= 12 else n
    start = max(1, n - trans_len)
    after_c = 0
    after_c_c = 0
    after_d = 0
    after_d_c = 0
    for i in range(start, n):
        if my[i - 1] == 'C':
            after_c += 1
            if op[i] == 'C':
                after_c_c += 1
        else:
            after_d += 1
            if op[i] == 'C':
                after_d_c += 1

    success_rate = after_c_c / after_c if after_c > 0 else recent_c_rate
    forgive_rate = after_d_c / after_d if after_d > 0 else 0.0
    exploitable = (
        after_d >= 1 and
        forgive_rate >= 0.65 and
        recent_c_rate >= 0.45
    ) or (
        op_d_total == 0 and
        my_d_total > 0 and
        recent_c_rate >= 0.5
    )
    unresponsive = (
        after_c >= 1 and
        after_c_c == 0 and
        recent_c_rate <= 0.2 and
        opp_d_streak >= 3
    )

    failed_test = False
    if n >= 3:
        for j in range(max(0, n - 8), n - 2):
            if (
                history[j] == ('D', 'D') and
                history[j + 1] == ('C', 'D') and
                history[j + 2] == ('D', 'D')
            ):
                failed_test = True
                break

    remaining = 100 - n

    if remaining <= 2:
        if last_op == 'D' or recent_c_rate <= 0.35:
            return 'D'
        if exploitable or op_d_total == 0 or recent_c_rate >= 0.75:
            return 'D'
        return 'C'

    if remaining <= 5:
        if exploitable and last_op == 'C':
            return 'D'
        if recent_c_rate <= 0.3:
            return 'D'
        if last_op == 'D':
            return 'D'
        if recent_c_rate >= 0.7:
            return 'C'

    if last_op == 'C':
        if exploitable:
            if op_d_total == 0:
                if rng.random() < 0.55:
                    return 'D'
            if remaining > 20:
                if rng.random() < 0.08:
                    return 'D'
            elif remaining > 10:
                if rng.random() < 0.22:
                    return 'D'
            else:
                if rng.random() < 0.5:
                    return 'D'
        return 'C'

    if last_me == 'C':
        prev = None
        if n >= 2:
            prev = history[-2]

        if prev == ('C', 'D'):
            return 'D'

        if prev == ('D', 'D'):
            if not failed_test and op_c_total > 0:
                return 'C'
            return 'D'

        if opp_d_streak == 1:
            if recent_c_rate >= 0.75 and op_d_total <= 2:
                if rng.random() < 0.45:
                    return 'C'
            if recent_c_rate >= 0.60 and success_rate >= 0.50:
                if rng.random() < 0.25:
                    return 'C'
            return 'D'

        if recent_c_rate <= 0.15:
            return 'D'

        if opp_d_streak <= 2 and recent_c_rate >= 0.60 and success_rate >= 0.60:
            if rng.random() < 0.30:
                return 'C'
            return 'D'

        return 'D'

    if op_c_total == 0:
        return 'D'

    if failed_test:
        if recent5_rate >= 0.2 and opp_d_streak <= 3:
            return 'C'
        if recent_c_rate >= 0.4 and success_rate >= 0.5:
            return 'C'
        if opp_d_streak >= 12 and rng.random() < 0.04:
            return 'C'
        return 'D'

    if unresponsive:
        if opp_d_streak >= 10 and recent_c_rate > 0.1 and rng.random() < 0.05:
            return 'C'
        return 'D'

    if recent_c_rate <= 0.1:
        p = 0.05 if op_c_total * 4 >= n else 0.01
    elif opp_d_streak < 3:
        p = 0.04
    elif opp_d_streak < 5:
        p = 0.35 if recent_c_rate >= 0.5 else 0.15
    elif opp_d_streak < 10:
        if recent_c_rate >= 0.5:
            p = 0.35
        elif op_c_total * 2 >= n:
            p = 0.22
        else:
            p = 0.08
    else:
        if recent_c_rate >= 0.25 and op_c_total * 3 >= n:
            p = 0.15
        else:
            p = 0.04

    if exploitable:
        p = max(p, 0.45)

    if rng.random() < p:
        return 'C'
    return 'D'
